def build_add(variant):
    if variant == "wrong_sum":
        return lambda a, b: a + b + 1
    if variant == "no_type_error":
        return lambda a, b: str(a) + str(b)

    def add(a, b):
        if isinstance(a, str) or isinstance(b, str):
            raise TypeError("numbers only")
        return a + b

    return add


def check(fn):
    try:
        return fn()
    except BaseException:
        return False


def run_add_tests(variant="correct"):
    add = build_add(variant)

    def raises_type_error():
        try:
            add("a", 1)
        except TypeError:
            return True
        return False

    return {
        "normal": check(lambda: add(2, 3) == 5),
        "edge": check(lambda: add(-1, 1) == 0),
        "raises_type_error": check(raises_type_error),
    }
